// Try to get a block from the lookahead buffer
    while (true) {
        // Check if lookahead buffer has free blocks
        if (lfs->lookahead > 0) {
            // Find the next free block in lookahead
            for (lfs_block_t i = 0; i < lfs->cfg->block_count; i++) {
                if (lfs->free[i / 32] & (1U << (i % 32))) {
                    // Found a free block
                    *block = i;
                    // Update lookahead state
                    lfs->free[i / 32] &= ~(1U << (i % 32));
                    lfs->lookahead--;
                    return 0;
                }
            }
        }

        // If lookahead is empty, scan for free blocks
        // This is a simplified version - actual littlefs has more complex logic
        for (lfs_block_t i = 0; i < lfs->cfg->block_count; i++) {
            if (lfs->free[i / 32] & (1U << (i % 32))) {
                *block = i;
                lfs->free[i / 32] &= ~(1U << (i % 32));
                return 0;
            }
        }

        return LFS_ERR_NOSPC;
    }

